import React, { useState } from 'react';
import './SellBike.css';
function SellBike() {
  const [formData, setFormData] = useState({
    brand: '',
    model: '',
    price: ''
  });

  const handleChange = e => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = e => {
    e.preventDefault();
    alert('Bike posted for sale: ' + JSON.stringify(formData));
    // Here you will send POST request to backend later
  };

  return (
    <div>
      <h2>Sell Your Bike</h2>
      <form onSubmit={handleSubmit}>
        <input name="brand" placeholder="Brand" onChange={handleChange} required className="form-control mb-2"/>
        <input name="model" placeholder="Model" onChange={handleChange} required className="form-control mb-2"/>
        <input name="price" placeholder="Price" onChange={handleChange} required className="form-control mb-2"/>
        <button className="btn btn-primary" type="submit">Submit</button>
      </form>
    </div>
  );
}

export default SellBike;
